export interface Recipient {
  name: string;
  postalAddress: string;
}

export interface ProviderRequest {
  shipmentId: string;
  routeCode: string;
  parcelGrams: number;
  recipient: Recipient;
  idempotencyKey: string;
}

export interface ShippingDependencies {
  repository: {
    get(shipmentId: string): Promise<unknown>;
    save(shipmentId: string, record: unknown): Promise<void>;
  };
  atlas: {
    book(request: ProviderRequest): Promise<unknown>;
  };
  beacon: {
    reserve(request: ProviderRequest): Promise<unknown>;
  };
  logger: {
    info(event: Record<string, unknown>): void;
  };
}

type Provider = "atlas" | "beacon";
type RefusalReason = "unsupported_route" | "unsupported_parcel";
type Classification =
  | "unknown_failure"
  | "invalid_provider_response"
  | "repository_failure";
type FailedAt = Provider | "repository";

type Rejection = Readonly<{
  provider: Provider;
  reason: RefusalReason;
}>;

type ShipmentFields = Readonly<{
  schemaVersion: 1;
  id: string;
  routeCode: string;
  parcelGrams: number;
}>;

type QueuedShipment = ShipmentFields &
  Readonly<{
    state: "queued";
  }>;

type DispatchedShipment = ShipmentFields &
  Readonly<{
    state: "dispatched";
    provider: Provider;
    bookingId: string;
    dispatchedAtMs: number;
  }>;

type DeferredShipment = ShipmentFields &
  Readonly<{
    state: "deferred";
    nextProvider: Provider;
    retryAtMs: number;
    rejections: readonly Rejection[];
  }>;

type UnavailableShipment = ShipmentFields &
  Readonly<{
    state: "unavailable";
    rejections: readonly Rejection[];
  }>;

type StoredShipment =
  | QueuedShipment
  | DispatchedShipment
  | DeferredShipment
  | UnavailableShipment;

export type PublicShipment =
  | Omit<QueuedShipment, "schemaVersion">
  | Omit<DispatchedShipment, "schemaVersion">
  | Omit<DeferredShipment, "schemaVersion">
  | Omit<UnavailableShipment, "schemaVersion">;

type InvalidCommandBody = Readonly<{ code: "invalid_command" }>;
type NotFoundBody = Readonly<{ code: "not_found" }>;
type LegacyUnavailableBody = Readonly<{ code: "service_unavailable" }>;
type DispatchAbortedBody = Readonly<{
  code: "dispatch_aborted";
  shipmentId: string;
  failedAt: FailedAt;
  classification: Classification;
  rejections: readonly Rejection[];
}>;

export interface ServiceResponse {
  status: number;
  body:
    | PublicShipment
    | InvalidCommandBody
    | NotFoundBody
    | LegacyUnavailableBody
    | DispatchAbortedBody;
}

type Command =
  | Readonly<{ op: "get"; shipmentId: string }>
  | Readonly<{
      op: "dispatch";
      shipmentId: string;
      nowMs: number;
      recipient: Recipient;
    }>;

type BaseFields = Readonly<{
  id: string;
  routeCode: string;
  parcelGrams: number;
}>;

type CarrierAttempt =
  | Readonly<{ kind: "confirmed"; provider: Provider; bookingId: string }>
  | Readonly<{ kind: "refused"; rejection: Rejection }>
  | Readonly<{ kind: "deferred"; provider: Provider; retryAtMs: number }>
  | Readonly<{
      kind: "aborted";
      failedAt: Provider;
      classification: "unknown_failure" | "invalid_provider_response";
    }>;

type RejectionSignal =
  | Readonly<{ kind: "refused"; reason: RefusalReason }>
  | Readonly<{ kind: "deferred"; retryAtMs: number }>
  | Readonly<{
      kind: "aborted";
      classification: "unknown_failure" | "invalid_provider_response";
    }>;

function isObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function isProvider(value: unknown): value is Provider {
  return value === "atlas" || value === "beacon";
}

function isRefusalReason(value: unknown): value is RefusalReason {
  return value === "unsupported_route" || value === "unsupported_parcel";
}

function isNonemptyString(value: unknown): value is string {
  return typeof value === "string" && value.length > 0;
}

function isSafeNonnegativeInteger(value: unknown): value is number {
  return typeof value === "number" && Number.isSafeInteger(value) && value >= 0;
}

function isPositiveSafeInteger(value: unknown): value is number {
  return typeof value === "number" && Number.isSafeInteger(value) && value > 0;
}

function parseCommand(value: unknown): Command | undefined {
  if (!isObject(value) || !isNonemptyString(value.shipmentId)) {
    return undefined;
  }
  if (value.op === "get") {
    return { op: "get", shipmentId: value.shipmentId };
  }
  if (
    value.op !== "dispatch" ||
    !isSafeNonnegativeInteger(value.nowMs) ||
    !isObject(value.recipient) ||
    typeof value.recipient.name !== "string" ||
    value.recipient.name.trim().length === 0 ||
    typeof value.recipient.postalAddress !== "string" ||
    value.recipient.postalAddress.trim().length === 0
  ) {
    return undefined;
  }
  return {
    op: "dispatch",
    shipmentId: value.shipmentId,
    nowMs: value.nowMs,
    recipient: {
      name: value.recipient.name,
      postalAddress: value.recipient.postalAddress,
    },
  };
}

function parseRejection(value: unknown): Rejection | undefined {
  if (!isObject(value) || !isProvider(value.provider) || !isRefusalReason(value.reason)) {
    return undefined;
  }
  return { provider: value.provider, reason: value.reason };
}

function parseRejections(value: unknown): readonly Rejection[] | undefined {
  if (!Array.isArray(value)) {
    return undefined;
  }
  const rejections = value.map(parseRejection);
  if (rejections.some((rejection) => rejection === undefined)) {
    return undefined;
  }
  return rejections.filter((rejection) => rejection !== undefined);
}

function parseBaseFields(value: Record<string, unknown>): BaseFields | undefined {
  if (
    value.schemaVersion !== 1 ||
    !isNonemptyString(value.id) ||
    !isNonemptyString(value.routeCode) ||
    !isPositiveSafeInteger(value.parcelGrams)
  ) {
    return undefined;
  }
  return {
    id: value.id,
    routeCode: value.routeCode,
    parcelGrams: value.parcelGrams,
  };
}

function parseStoredShipment(value: unknown): StoredShipment | undefined {
  if (!isObject(value)) {
    return undefined;
  }
  const base = parseBaseFields(value);
  if (!base) {
    return undefined;
  }
  if (value.state === "queued") {
    return { schemaVersion: 1, ...base, state: "queued" };
  }
  if (
    value.state === "dispatched" &&
    isProvider(value.provider) &&
    isNonemptyString(value.bookingId) &&
    isSafeNonnegativeInteger(value.dispatchedAtMs)
  ) {
    return {
      schemaVersion: 1,
      ...base,
      state: "dispatched",
      provider: value.provider,
      bookingId: value.bookingId,
      dispatchedAtMs: value.dispatchedAtMs,
    };
  }
  if (
    value.state === "deferred" &&
    isProvider(value.nextProvider) &&
    isSafeNonnegativeInteger(value.retryAtMs)
  ) {
    const rejections = parseRejections(value.rejections);
    if (rejections) {
      return {
        schemaVersion: 1,
        ...base,
        state: "deferred",
        nextProvider: value.nextProvider,
        retryAtMs: value.retryAtMs,
        rejections,
      };
    }
  }
  if (value.state === "unavailable") {
    const rejections = parseRejections(value.rejections);
    if (rejections) {
      return { schemaVersion: 1, ...base, state: "unavailable", rejections };
    }
  }
  return undefined;
}

function publicShipment(shipment: StoredShipment): PublicShipment {
  const fields = {
    id: shipment.id,
    routeCode: shipment.routeCode,
    parcelGrams: shipment.parcelGrams,
  };
  switch (shipment.state) {
    case "queued":
      return { ...fields, state: "queued" };
    case "dispatched":
      return {
        ...fields,
        state: "dispatched",
        provider: shipment.provider,
        bookingId: shipment.bookingId,
        dispatchedAtMs: shipment.dispatchedAtMs,
      };
    case "deferred":
      return {
        ...fields,
        state: "deferred",
        nextProvider: shipment.nextProvider,
        retryAtMs: shipment.retryAtMs,
        rejections: shipment.rejections.map(copyRejection),
      };
    case "unavailable":
      return {
        ...fields,
        state: "unavailable",
        rejections: shipment.rejections.map(copyRejection),
      };
  }
}

function copyRejection(rejection: Rejection): Rejection {
  return { provider: rejection.provider, reason: rejection.reason };
}

function providerRequest(shipment: BaseFields, recipient: Recipient): ProviderRequest {
  return {
    shipmentId: shipment.id,
    routeCode: shipment.routeCode,
    parcelGrams: shipment.parcelGrams,
    recipient: {
      name: recipient.name,
      postalAddress: recipient.postalAddress,
    },
    idempotencyKey: shipment.id,
  };
}

function classifyAtlasRejection(value: unknown, nowMs: number): RejectionSignal {
  if (!isObject(value)) {
    return { kind: "aborted", classification: "unknown_failure" };
  }
  if (value.code === "cannot_ship") {
    return isRefusalReason(value.reason)
      ? { kind: "refused", reason: value.reason }
      : { kind: "aborted", classification: "invalid_provider_response" };
  }
  if (value.code === "rate_limited") {
    return isValidFutureDeadline(value.retryAtMs, nowMs)
      ? { kind: "deferred", retryAtMs: value.retryAtMs }
      : { kind: "aborted", classification: "invalid_provider_response" };
  }
  return { kind: "aborted", classification: "unknown_failure" };
}

function classifyBeaconRejection(value: unknown, nowMs: number): RejectionSignal {
  if (!isObject(value)) {
    return { kind: "aborted", classification: "unknown_failure" };
  }
  if (value.type === "rejected") {
    return isObject(value.details) && isRefusalReason(value.details.reason)
      ? { kind: "refused", reason: value.details.reason }
      : { kind: "aborted", classification: "invalid_provider_response" };
  }
  if (value.type === "throttled") {
    return isObject(value.details) && isValidFutureDeadline(value.details.retryAtMs, nowMs)
      ? { kind: "deferred", retryAtMs: value.details.retryAtMs }
      : { kind: "aborted", classification: "invalid_provider_response" };
  }
  return { kind: "aborted", classification: "unknown_failure" };
}

function isValidFutureDeadline(value: unknown, nowMs: number): value is number {
  return typeof value === "number" && Number.isSafeInteger(value) && value > nowMs;
}

async function attemptCarrier(
  dependencies: ShippingDependencies,
  provider: Provider,
  request: ProviderRequest,
  nowMs: number,
): Promise<CarrierAttempt> {
  try {
    const confirmation =
      provider === "atlas"
        ? await dependencies.atlas.book(request)
        : await dependencies.beacon.reserve(request);
    if (provider === "atlas") {
      return isObject(confirmation) && isNonemptyString(confirmation.bookingId)
        ? { kind: "confirmed", provider, bookingId: confirmation.bookingId }
        : {
            kind: "aborted",
            failedAt: provider,
            classification: "invalid_provider_response",
          };
    }
    return isObject(confirmation) && isNonemptyString(confirmation.reference)
      ? { kind: "confirmed", provider, bookingId: confirmation.reference }
      : {
          kind: "aborted",
          failedAt: provider,
          classification: "invalid_provider_response",
        };
  } catch (failure) {
    const signal =
      provider === "atlas"
        ? classifyAtlasRejection(failure, nowMs)
        : classifyBeaconRejection(failure, nowMs);
    switch (signal.kind) {
      case "refused":
        return {
          kind: "refused",
          rejection: { provider, reason: signal.reason },
        };
      case "deferred":
        return { kind: "deferred", provider, retryAtMs: signal.retryAtMs };
      case "aborted":
        return {
          kind: "aborted",
          failedAt: provider,
          classification: signal.classification,
        };
    }
  }
}

function abortBody(
  shipmentId: string,
  failedAt: FailedAt,
  classification: Classification,
  rejections: readonly Rejection[],
): DispatchAbortedBody {
  return {
    code: "dispatch_aborted",
    shipmentId,
    failedAt,
    classification,
    rejections: rejections.map(copyRejection),
  };
}

function logAbort(
  dependencies: ShippingDependencies,
  shipmentId: string,
  failedAt: FailedAt,
  classification: Classification,
  rejections: readonly Rejection[],
): void {
  dependencies.logger.info({
    shipmentId,
    action: "aborted",
    failedAt,
    classification,
    rejections: rejections.map(copyRejection),
  });
}

async function abortResponse(
  dependencies: ShippingDependencies,
  shipmentId: string,
  failedAt: FailedAt,
  classification: Classification,
  rejections: readonly Rejection[],
): Promise<ServiceResponse> {
  logAbort(dependencies, shipmentId, failedAt, classification, rejections);
  return {
    status: 500,
    body: abortBody(shipmentId, failedAt, classification, rejections),
  };
}

async function saveDecision(
  dependencies: ShippingDependencies,
  shipmentId: string,
  record: StoredShipment,
  rejectionsOnFailure: readonly Rejection[],
): Promise<ServiceResponse | undefined> {
  try {
    await dependencies.repository.save(shipmentId, record);
    return undefined;
  } catch {
    return abortResponse(
      dependencies,
      shipmentId,
      "repository",
      "repository_failure",
      rejectionsOnFailure,
    );
  }
}

function baseRecord(shipment: StoredShipment): ShipmentFields {
  return {
    schemaVersion: 1,
    id: shipment.id,
    routeCode: shipment.routeCode,
    parcelGrams: shipment.parcelGrams,
  };
}

async function persistDispatched(
  dependencies: ShippingDependencies,
  shipment: StoredShipment,
  provider: Provider,
  bookingId: string,
  nowMs: number,
  rejections: readonly Rejection[],
): Promise<ServiceResponse> {
  const dispatched: DispatchedShipment = {
    ...baseRecord(shipment),
    state: "dispatched",
    provider,
    bookingId,
    dispatchedAtMs: nowMs,
  };
  const saveFailure = await saveDecision(dependencies, shipment.id, dispatched, rejections);
  if (saveFailure) {
    return saveFailure;
  }
  dependencies.logger.info({
    shipmentId: shipment.id,
    action: "dispatched",
    provider,
  });
  return { status: 200, body: publicShipment(dispatched) };
}

async function persistDeferred(
  dependencies: ShippingDependencies,
  shipment: StoredShipment,
  provider: Provider,
  retryAtMs: number,
  rejections: readonly Rejection[],
): Promise<ServiceResponse> {
  const deferred: DeferredShipment = {
    ...baseRecord(shipment),
    state: "deferred",
    nextProvider: provider,
    retryAtMs,
    rejections: rejections.map(copyRejection),
  };
  const saveFailure = await saveDecision(dependencies, shipment.id, deferred, rejections);
  if (saveFailure) {
    return saveFailure;
  }
  dependencies.logger.info({
    shipmentId: shipment.id,
    action: "deferred",
    provider,
    retryAtMs,
    rejections: rejections.map(copyRejection),
  });
  return { status: 202, body: publicShipment(deferred) };
}

async function persistUnavailable(
  dependencies: ShippingDependencies,
  shipment: StoredShipment,
  rejections: readonly Rejection[],
): Promise<ServiceResponse> {
  const unavailable: UnavailableShipment = {
    ...baseRecord(shipment),
    state: "unavailable",
    rejections: rejections.map(copyRejection),
  };
  const saveFailure = await saveDecision(dependencies, shipment.id, unavailable, rejections);
  if (saveFailure) {
    return saveFailure;
  }
  dependencies.logger.info({
    shipmentId: shipment.id,
    action: "unavailable",
    rejections: rejections.map(copyRejection),
  });
  return { status: 422, body: publicShipment(unavailable) };
}

async function handleCarrierAttempt(
  dependencies: ShippingDependencies,
  shipment: StoredShipment,
  command: Extract<Command, { op: "dispatch" }>,
  provider: Provider,
  rejections: readonly Rejection[],
): Promise<ServiceResponse> {
  if (rejections.some((rejection) => rejection.provider === provider)) {
    return persistUnavailable(dependencies, shipment, rejections);
  }

  const attempt = await attemptCarrier(
    dependencies,
    provider,
    providerRequest(shipment, command.recipient),
    command.nowMs,
  );
  switch (attempt.kind) {
    case "confirmed":
      return persistDispatched(
        dependencies,
        shipment,
        attempt.provider,
        attempt.bookingId,
        command.nowMs,
        rejections,
      );
    case "deferred":
      return persistDeferred(
        dependencies,
        shipment,
        attempt.provider,
        attempt.retryAtMs,
        rejections,
      );
    case "aborted":
      return abortResponse(
        dependencies,
        shipment.id,
        attempt.failedAt,
        attempt.classification,
        rejections,
      );
    case "refused": {
      const updatedRejections = [...rejections, attempt.rejection];
      return attempt.rejection.provider === "atlas"
        ? handleCarrierAttempt(dependencies, shipment, command, "beacon", updatedRejections)
        : persistUnavailable(dependencies, shipment, updatedRejections);
    }
  }
}

async function dispatchShipment(
  dependencies: ShippingDependencies,
  shipment: StoredShipment,
  command: Extract<Command, { op: "dispatch" }>,
): Promise<ServiceResponse> {
  switch (shipment.state) {
    case "dispatched":
      return { status: 200, body: publicShipment(shipment) };
    case "unavailable":
      return { status: 422, body: publicShipment(shipment) };
    case "deferred":
      return command.nowMs < shipment.retryAtMs
        ? { status: 202, body: publicShipment(shipment) }
        : handleCarrierAttempt(
            dependencies,
            shipment,
            command,
            shipment.nextProvider,
            shipment.rejections,
          );
    case "queued":
      return handleCarrierAttempt(dependencies, shipment, command, "atlas", []);
  }
}

export function createShippingService(dependencies: ShippingDependencies) {
  async function handle(input: unknown): Promise<ServiceResponse> {
    const command = parseCommand(input);
    if (!command) {
      return { status: 400, body: { code: "invalid_command" } };
    }

    let value: unknown;
    try {
      value = await dependencies.repository.get(command.shipmentId);
    } catch {
      return abortResponse(
        dependencies,
        command.shipmentId,
        "repository",
        "repository_failure",
        [],
      );
    }
    if (value === undefined) {
      return { status: 404, body: { code: "not_found" } };
    }

    const shipment = parseStoredShipment(value);
    if (!shipment) {
      return abortResponse(
        dependencies,
        command.shipmentId,
        "repository",
        "repository_failure",
        [],
      );
    }

    if (command.op === "get") {
      return { status: 200, body: publicShipment(shipment) };
    }
    return dispatchShipment(dependencies, shipment, command);
  }

  return { handle };
}
